-- Dansk portion 3 del 2/3: 167 MC-spørgsmål på sværhedsskalaen 1-10.000, niveau 3333-6563.
-- Del af de 5.000 nye danskopgaver. Skrevet fra bunden til dansk folkeskole, 3.-9. klasse.
-- Genereret af tools/questions/build-danish-5000.mjs; ret i tools/questions/fixtures/danish-5000/, ikke her.
-- Kræver migration A (20261020120000_difficulty_scale_a): kolonnen questions.difficulty_level.
--
-- Niveau: hver opgave har et eksplicit difficulty_level (forfatterens skøn, ikke en måling).
-- target_grade/difficulty_band er afledt baglæns af niveauet (cellen i §4.1).
--
-- INAKTIV VED INDSÆTTELSEN: alle rækker får is_active=false og metadata.level_batch='danish3'.
-- Aktivering er en SEPARAT migration efter dokumenteret stikprøvekontrol og særskilt ejergodkendelse.
-- Må KUN anvendes via apply_migration med særskilt ejer-autorisation (D-110).

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band, difficulty_level)
SELECT
  jsonb_build_object('question', e->>'q', 'options', e->'o', 'correct', e->>'a',
                     'accepted_answers', jsonb_build_array(e->>'a'), 'review_text', e->>'r'),
  'mc', 'short',
  jsonb_build_object('concepts', jsonb_build_array(m.concept), 'cognitive_skill', m.skill,
                     'difficulty_type', m.dtype, 'misconception_type', m.mis,
                     'challenge_role', e->>'role', 'insight_type', e->>'insight',
                     'practice_variant', e->>'variant',
                     'level_batch', 'danish3', 'domain', 'danish'),
  'mc_single', (e->>'b')::int, 'auto', false, 'danish', (e->>'g')::int,
  (e->>'b')::int, (e->>'l')::int
FROM jsonb_array_elements($$[
{"l":3333,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Sæt det rigtige ord ind: 'Brevet har ___ i postkassen i en hel uge.'","o":["liggede","lagget","lagt","ligget"],"a":"ligget","r":"Brevet har bare været i ro, så ordet kommer af 'ligge'. Efter 'har' ender det på -et."},
{"l":3355,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad kaldes den kraft, der trækker alting ned mod Jorden?","o":["tyngdekraften","friktionen","spændingen","opdriften"],"a":"tyngdekraften","r":"Tyngdekraften er grunden til, at en bold falder ned, når du slipper den. Opdrift virker den modsatte vej i vand."},
{"l":3377,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad er der sket, når nogen har 'trukket det korteste strå'?","o":["De har vundet en lodtrækning","De er kommet dårligst ud af det","De har fundet den letteste vej","De har bygget noget af naturmaterialer"],"a":"De er kommet dårligst ud af det","r":"Vendingen kommer af en gammel måde at trække lod på: Den, der fik det korte strå, tabte."},
{"l":3397,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Amina og Clara byggede en hule i skoven. Clara ville have døren mod søen. Amina ville have den mod solen. Efter to dages skænderi rev de den ene væg ned og lavede en dør mere. Bagefter var det blevet den bedste hule i skoven.' Hvad er budskabet i historien?","o":["Man skal altid gøre, som den anden siger","Den, der bliver ved længst, får sin vilje","Man kan godt finde en løsning, selvom man er uenige","En god hule skal altid have to døre"],"a":"Man kan godt finde en løsning, selvom man er uenige","r":"Pigerne er uenige, men finder en løsning, som bliver bedre, end hvis den ene havde fået ret."},
{"l":3416,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilket tegn skal slutte sætningen: 'Emil spurgte læreren, hvornår frikvarteret begyndte'?","o":["spørgsmålstegn","udråbstegn","kolon","punktum"],"a":"punktum","r":"Sætningen fortæller, at Emil spurgte, men den stiller ikke selv et spørgsmål. Det er et indirekte spørgsmål, og det slutter med punktum."},
{"l":3435,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Hvad lærer man af historien om hyrdedrengen, der råbte ulv for sjov?","o":["Den, der lyver tit, bliver ikke troet","Man skal altid passe på ulve i skoven","Hyrder skal have en hund med på marken","Man skal råbe højt, hvis man vil have hjælp"],"a":"Den, der lyver tit, bliver ikke troet","r":"Da ulven virkelig kommer, tror ingen længere på drengen. Hvis man lyver tit, holder folk op med at tro på en."},
{"l":3454,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvad er genstandsleddet her: 'Malthe reparerer den gamle knallert.'","o":["Malthe","den gamle knallert","reparerer","Malthe reparerer"],"a":"den gamle knallert","r":"Spørg: Hvad reparerer Malthe? Svaret 'den gamle knallert' er genstandsleddet."},
{"l":3476,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvad er stavet rigtigt? 'Min søster er to år ___ end mig.'","o":["yngere","ynger","yngre","yngrere"],"a":"yngre","r":"Ordet er højere grad af 'ung'. Det er uregelmæssigt og ender på -re."},
{"l":3497,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad kaldes et materiale som gummi, der ikke lader elektrisk strøm løbe igennem?","o":["en leder","en generator","en magnet","en isolator"],"a":"en isolator","r":"En isolator holder strømmen inde. Derfor er ledninger pakket ind i plastik eller gummi."},
{"l":3513,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Pumpen ved søen i Sønderlund er gået i stykker. Derfor har området i ugevis været oversvømmet, og stien er lukket. Kommunen oplyser, at reparationen tager tre uger mere. Indtil da må gående tage omvejen forbi skolen.' Hvad skete der, og hvad førte det til?","o":["Pumpen gik i stykker, så området blev oversvømmet","Stien blev lukket, så pumpen gik i stykker","Området blev oversvømmet, så pumpen gik i stykker","Pumpen gik i stykker, så skolen blev lukket"],"a":"Pumpen gik i stykker, så området blev oversvømmet","r":"Ordet 'derfor' viser det: Først gik pumpen i stykker, og derfor blev området oversvømmet og stien lukket."},
{"l":3535,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad er 'ækvator'?","o":["det varmeste sted i den største ørken i Afrika","en tænkt linje rundt om Jorden midt mellem polerne","en strøm i havet, der bringer varmt vand mod nord","den tid på året, hvor dag og nat er lige lange"],"a":"en tænkt linje rundt om Jorden midt mellem polerne","r":"Ækvator deler Jorden i en nordlig og en sydlig halvkugle. Den findes kun på kortet, ikke i virkeligheden."},
{"l":3553,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilken sætning om Filip og skoene står i førdatid?","o":["Filip har pudset skoene.","Filip pudsede skoene.","Filip havde pudset skoene.","Filip pudser skoene."],"a":"Filip havde pudset skoene.","r":"Førdatid dannes med 'havde' og tillægsform. 'Har pudset' er førnutid."},
{"l":3575,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvordan staves flertal her? 'Landmanden malker sine ___ morgen og aften.'","o":["koer","køre","kør","køer"],"a":"køer","r":"Ental er 'ko'. I flertal skifter o til ø, og ordet ender på -er."},
{"l":3595,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket tillægsord dannet af 'frugt' bruger man om jord, hvor meget kan gro?","o":["frugtbar","frugtløs","frugtig","frugtagtig"],"a":"frugtbar","r":"Endelsen -bar kan vise, at noget kan bære eller give noget. Frugtløs betyder det modsatte: uden resultat."},
{"l":3610,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad vil ordsproget 'Lille tue kan vælte stort læs' sige?","o":["Tunge vogne skal køre langsomt","Små ting kan få store følger","Store mennesker er altid stærkest","Man skal rydde op i naturen"],"a":"Små ting kan få store følger","r":"En tue er en lille forhøjning i jorden. Den er lille, men kan alligevel vælte en stor vogn med hø."},
{"l":3630,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Glas kan genbruges igen og igen uden at blive dårligere. Glasset bliver knust, smeltet og formet til nye flasker. Det kræver mindre energi end at lave nyt glas fra sand. Hver flaske, du afleverer, sparer altså på energien.' Hvad er tekstens hovedpointe?","o":["Glas er lavet af sand fra stranden","Glas går let i stykker og skal smides ud","Det er en god idé at aflevere glas til genbrug","Det er dyrt at smelte glas til nye flasker"],"a":"Det er en god idé at aflevere glas til genbrug","r":"Alle oplysninger fører frem til den sidste sætning: Genbrug af glas sparer energi."},
{"l":3652,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilket forholdsord hører til: 'Jonathan er vant ___ at stå tidligt op.'","o":["med","for","af","til"],"a":"til","r":"Når man har gjort noget mange gange, siger man 'vant til': vant til kulde, vant til at stå tidligt op."},
{"l":3674,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Sæt det rigtige ord ind: 'Musen smuttede ned i ___ i væggen.'","o":["hullet","hulet","hulled","hullede"],"a":"hullet","r":"Grundordet er 'hul'. I bestemt form fordobles l'et, fordi u'et er kort."},
{"l":3693,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Hanne gik langs stranden med hunden og fandt et stykke rav. Hun kunne ikke tro sine egne øjne. Rav er harpiks fra træer, som stivnede for millioner af år siden. Nogle gange sidder der et insekt inde i det. Hanne tog det op og holdt det mod lyset.' Hvorfor holder Hanne ravet mod lyset?","o":["Hun vil se, om det kan smelte af solen","Hun vil se, om der er et insekt i det","Hun vil se, hvor gammelt det er","Hun vil tørre det, efter det var i vandet"],"a":"Hun vil se, om der er et insekt i det","r":"Teksten nævner lige før, at der kan sidde insekter i rav. Lys gør det muligt at se ind i stenen."},
{"l":3715,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord betyder det sted i naturen, hvor en bestemt art lever?","o":["population","fødekæde","habitat","klima"],"a":"habitat","r":"Et habitat er et levested. Isfuglens habitat er for eksempel rene åer med stejle brinker, hvor den kan grave sin rede."},
{"l":3730,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad mangler: 'En sø med planter, fisk, fugle og alt det, de lever af, er et ___.'","o":["kontinent","klima","mineral","økosystem"],"a":"økosystem","r":"I et økosystem hænger alt det levende og omgivelserne sammen. Ændrer man én ting, påvirker det resten."},
{"l":3752,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad er en 'gletsjer'?","o":["en stor ismasse, der langsomt flytter sig","en varm kilde, der sprøjter vand op i luften","en dyb og smal dal, som havet er trængt ind i","en stor bjergkæde med sne på de højeste toppe"],"a":"en stor ismasse, der langsomt flytter sig","r":"En gletsjer er dannet af sne, der er presset sammen til is. Isen glider langsomt nedad. En smal dal med havvand er derimod en fjord."},
{"l":3773,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Find forholdsordsleddet: 'Drengene bygger en hule bag skuret.'","o":["Drengene","bag skuret","en hule","bygger"],"a":"bag skuret","r":"'Bag' er et forholdsord, og 'skuret' hører med til det. Tilsammen er de et forholdsordsled."},
{"l":3790,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"På en tegning af et hus står der 'målestok 1:100'. Hvad betyder det?","o":["100 cm på tegningen er 1 cm i virkeligheden","Tegningen består af 100 små tegninger","1 cm på tegningen er 100 cm i virkeligheden","Huset har plads til 100 personer i alt"],"a":"1 cm på tegningen er 100 cm i virkeligheden","r":"Målestokken fortæller, hvor mange gange tegningen er formindsket. Her er alt 100 gange mindre end i virkeligheden."},
{"l":3812,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Ordet 'renæssance' kommer fra fransk. Hvad betyder det?","o":["opdagelse","fremskridt","forandring","genfødsel"],"a":"genfødsel","r":"I renæssancen blev man optaget af oldtidens græske og romerske kunst og viden, som på en måde blev født på ny."},
{"l":3828,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvad skal der stå? 'Hun har ___ mig et stort kram.'","o":["givet","gevet","givvet","gived"],"a":"givet","r":"Efter 'har' ender ordet på -et. I'et er langt, så der er kun ét v."},
{"l":3850,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Vælg stavemåden: 'Hvad er der ___ med din cykel?'","o":["skedt","sket","skeet","skæt"],"a":"sket","r":"Navnemåden er 'at ske'. Kort tillægsform får bare et t på."},
{"l":3872,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Find den rigtige form: 'Hesten har ___ vognen hele vejen hjem.'","o":["truket","trækket","trukket","trækkede"],"a":"trukket","r":"Ordet 'trække' skifter til u efter 'har'. K'et er dobbelt, fordi u'et er kort."},
{"l":3891,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Efter hvilket ord skal kommaet stå: 'Hvem der vandt kampen ved jeg ikke.'?","o":["vandt","ved","jeg","kampen"],"a":"kampen","r":"'Hvem der vandt kampen' er en ledsætning, der står først. Bagefter følger hovedsætningen 'ved jeg ikke'."},
{"l":3907,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Rosa havde tegnet sin klasse til skolens udstilling. Hun tegnede alle eleverne og læreren. Da hun skulle hænge tegningen op, stoppede hun og tog en blyant frem. Hun tegnede en lille mand ved siden af med et stort nøgleknippe og en kost. Uden ham ville skolen jo gå i stå, tænkte hun.' Hvem er den lille mand nok?","o":["Skolens pedel","En ny lærer på skolen","En mand, hun har set på gaden","En rolle fra en bog, hun har læst"],"a":"Skolens pedel","r":"Nøgler og en kost hører til en, der passer skolen, og Rosa tænker, at skolen ikke kan undvære ham. Det passer på pedellen."},
{"l":3927,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Vælg den rigtige form: 'Hvem har ___ kampen om pokalen?'","o":["vunnet","vundet","vundt","vindet"],"a":"vundet","r":"Ordet 'vinde' skifter til u efter 'har'. D'et skrives, selvom det er stumt."},
{"l":3948,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvor mange kommaer mangler der i: 'Hvis det bliver koldt i aften skal du tage hue vanter halstørklæde og støvler på.'?","o":["to","fire","tre","fem"],"a":"tre","r":"Der skal ét komma efter ledsætningen, der slutter med 'aften'. Opremsningen skal have to: efter 'hue' og efter 'vanter'."},
{"l":3970,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad gør den, der 'løber panden mod en mur'?","o":["Træner hårdt for at blive bedre til sport","Skynder sig ind, før regnen begynder","Får hjælp af andre til at løse en opgave","Bliver ved med noget, der ikke kan lykkes"],"a":"Bliver ved med noget, der ikke kan lykkes","r":"En mur giver ikke efter. Vendingen bruges, når man prøver igen og igen uden at komme nogen vegne."},
{"l":3986,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Tre af begyndelserne er ledsætninger, der kræver komma bagefter. Hvilken er ikke en ledsætning?","o":["Efter den lange tur","Da turen var slut","Mens vi gik turen","Hvis turen bliver lang"],"a":"Efter den lange tur","r":"'Efter den lange tur' har intet udsagnsord og er ikke en ledsætning. De tre andre har både grundled og udsagnsled."},
{"l":4010,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"I H.C. Andersens 'Nattergalen' får kejseren en kunstig fugl. Hvad sker der med den?","o":["Den flyver væk fra slottet en stormfuld nat","Den går i stykker, så den næsten ikke kan synge mere","Den bliver til en rigtig fugl af kød og blod","Den bliver sendt tilbage til kejseren i Japan"],"a":"Den går i stykker, så den næsten ikke kan synge mere","r":"Den kunstige fugl er flot, men den er bare en maskine, og maskiner kan gå i stykker. Til sidst er det den ægte nattergal, der synger for kejseren."},
{"l":4030,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Læreren skriver, at en forklaring er 'overfladisk'. Hvad er problemet?","o":["Den er alt for lang","Den er skrevet for småt","Den går ikke i dybden","Den handler om havet"],"a":"Den går ikke i dybden","r":"En overfladisk forklaring bliver på overfladen og tager kun det letteste med. Den forklarer ikke rigtig, hvordan tingene hænger sammen."},
{"l":4048,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilket ord indleder ledsætningen: 'Jeg bliver glad, når du ringer.'","o":["glad","bliver","ringer","når"],"a":"når","r":"'Når' står først i ledsætningen og knytter den til hovedsætningen. Det er et bindeord."},
{"l":4070,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilket af bindeordene gør den sidste del til en ledsætning: 'Vi kom for sent, ___ bussen var forsinket.'","o":["fordi","og","men","eller"],"a":"fordi","r":"Prøv at læse delen alene: 'fordi bussen var forsinket' kan ikke stå selv, så det er en ledsætning. Efter 'og', 'men' og 'eller' ville den være en hovedsætning."},
{"l":4090,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Mårhunden kaldes en 'invasiv art' i Danmark. Hvad vil det sige?","o":["Den har altid levet her og er næsten forsvundet","Den er kommet hertil udefra og skader naturen her","Den kan kun leve i haver og parker i byerne","Den er fredet, fordi den er meget sjælden i Danmark"],"a":"Den er kommet hertil udefra og skader naturen her","r":"En invasiv art er kommet til et nyt sted og breder sig så meget, at den skader de dyr og planter, der lever der i forvejen."},
{"l":4112,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad kaldes forvandlingen fra haletudse til frø?","o":["fotosyntese","evolution","metamorfose","fordøjelse"],"a":"metamorfose","r":"Metamorfose er græsk for forvandling. Evolution sker derimod over mange generationer, ikke i det enkelte dyrs liv."},
{"l":4127,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad er 'drivhuseffekten'?","o":["at planter vokser hurtigere i et glashus","at solens lys bliver svagere om vinteren","at havets vand bliver saltere med tiden","at gasser i luften holder på Jordens varme"],"a":"at gasser i luften holder på Jordens varme","r":"Ligesom glas i et drivhus holder drivhusgasser på varmen. Uden dem ville Jorden være alt for kold, men for meget af dem gør den for varm."},
{"l":4149,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Har du tænkt på, hvor maden i dit køleskab kommer fra? Danske æbler, der sælges i marts, har ofte ligget på køl i månedsvis. Æbler fra andre verdensdele er sejlet tusindvis af kilometer. Begge dele koster energi. Det er derfor ikke altid let at sige, hvad der er bedst for miljøet.' Hvad er tekstens konklusion?","o":["At det ikke er let at sige, hvilke æbler der er bedst","At danske æbler altid er bedst for miljøet","At æbler fra andre lande altid er bedst","At man helt skal lade være med at købe æbler"],"a":"At det ikke er let at sige, hvilke æbler der er bedst","r":"Teksten viser, at begge slags æbler koster energi. Derfor kan man ikke give et enkelt svar."},
{"l":4169,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Udfyld sætningen: 'Det er en gammel ___ at danse om juletræet.'","o":["tredition","tradition","tradision","traddition"],"a":"tradition","r":"Ordet ender på -tion, og der er kun ét d."},
{"l":4187,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad var et 'andelsmejeri'?","o":["et mejeri, som kongen ejede selv","et mejeri, der kun lavede ost","et mejeri, som bønderne ejede sammen","et mejeri, der lå inde i en by"],"a":"et mejeri, som bønderne ejede sammen","r":"En andel er en del af noget. Bønderne gik sammen om mejeriet, ejede hver en andel og delte overskuddet."},
{"l":4203,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Klassens hamster, Bob, var væk en hel weekend. Mandag fandt Nadia ham i pedellens frakke. Bob havde spist hul på en lomme med en ostemad. Pedellen sagde, at det nok var den bedste kollega, han nogensinde havde haft. Hele klassen grinede.' Hvad er stemningen, da Bob bliver fundet?","o":["Alvorlig og trist","Spændt og nervøs","Stolt og højtidelig","Lettet og munter"],"a":"Lettet og munter","r":"Hamsteren er fundet, og pedellens spøg får alle til at grine, så stemningen er glad."},
{"l":4225,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Hvad kaldes et indlæg, som en almindelig læser sender til en avis?","o":["et læserbrev","en leder","en reportage","en anmeldelse"],"a":"et læserbrev","r":"I et læserbrev kan alle give deres mening til kende. Det er skrevet af en læser og ikke af avisens journalister."},
{"l":4246,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvad skal der stå? 'Man skal være ___, når man fisker, for det tager tid.'","o":["tålmodi","tålmodig","tolmodig","tålmoddig"],"a":"tålmodig","r":"Ordet ender på -ig, selvom g'et er stumt, og det har ét d."},
{"l":4268,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvordan skrives vendingen i sætningen? 'Du kan dække bord, og ___ laver jeg sovsen.'","o":["imellemtiden","i mellem tiden","i mellemtiden","i melletiden"],"a":"i mellemtiden","r":"Vendingen skrives i to ord: 'i' for sig og 'mellemtiden' i ét."},
{"l":4289,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilken ordklasse har 'langt' i sætningen: 'Bolden fløj langt ud over banen.'","o":["tillægsord","navneord","udsagnsord","biord"],"a":"biord","r":"'Langt' siger her noget om udsagnsordet 'fløj', altså hvor bolden fløj hen. Så er det et biord. I 'et langt løb' ville det være et tillægsord."},
{"l":4310,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Mange tror, at en høj pris gør maden sund. Men en sund ret behøver ikke at være dyr. I en undersøgelse sammenlignede man 50 retter fra to supermarkeder. De billigste var ikke mindre sunde end de dyreste. Det, der betød mest, var mængden af sukker og fedt.' Hvad var undersøgelsens resultat?","o":["At prisen ikke afgjorde, hvor sund retten var","At dyre retter altid indeholder mest sukker","At billige retter altid er de sundeste","At supermarkeder sælger for få sunde retter"],"a":"At prisen ikke afgjorde, hvor sund retten var","r":"Billige retter var ikke mindre sunde end dyre. Det, der talte, var indholdet, ikke prisen."},
{"l":4328,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Cyklen tilhører Lars. Hvilken form er rigtig i sætningen: '___ cykel står i skuret.'?","o":["Lars's","Lars'","Lar's","Larss"],"a":"Lars'","r":"Navne, der ender på s, får kun en apostrof i ejefald. Der skal ikke et ekstra s på."},
{"l":4347,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilket ord i sætningen skal skrives med stort: 'Vi så en spansk film om to svenskere på vej til grækenland.'?","o":["spansk","svenskere","grækenland","film"],"a":"grækenland","r":"Lande er navne og skrives med stort: Grækenland. Ord, der er afledt af landenavne, som 'spansk' og 'svenskere', skrives med lille."},
{"l":4366,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilket tegn skal slutte sætningen: 'Hun spurgte, om vi ville med'?","o":["spørgsmålstegn","udråbstegn","kolon","punktum"],"a":"punktum","r":"Det er et indirekte spørgsmål: Sætningen fortæller, at nogen spurgte. Derfor slutter den med punktum."},
{"l":4388,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"'Og' er et bindeord i sætningen 'Kaja og Rasmus bager boller.' Hvad hedder ordklassen på latin?","o":["konjunktion","præposition","interjektion","numerale"],"a":"konjunktion","r":"Konjunktion er det latinske navn for bindeord. Ordet betyder noget i retning af 'sammenbinding'."},
{"l":4406,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvad er rigtigt? 'Lommelygtens ___ er fladt, så den lyser ikke.'","o":["batterie","batteri","baterri","bateri"],"a":"batteri","r":"Ordet har dobbelt t og ét r, og det ender på -eri uden e til sidst."},
{"l":4423,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilket ord skal efterfølges af komma i sætningen 'Hvis det regner i morgen bliver kampen aflyst.'?","o":["regner","bliver","morgen","kampen"],"a":"morgen","r":"Ledsætningen 'Hvis det regner i morgen' slutter efter 'morgen'. Derfor skal kommaet stå dér."},
{"l":4443,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilken sætning er 'Kasper skrev en sang.' sat i førnutid?","o":["Kasper havde skrevet en sang.","Kasper har skrev en sang.","Kasper skriver en sang.","Kasper har skrevet en sang."],"a":"Kasper har skrevet en sang.","r":"Førnutid består af 'har' og tillægsform. Efter 'har' kan datiden 'skrev' ikke stå."},
{"l":4465,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilket led står lige efter udsagnsleddet i: 'Om aftenen spiller vi ofte skak.'?","o":["grundleddet","genstandsleddet","hensynsleddet","forholdsordsleddet"],"a":"grundleddet","r":"Når noget andet end grundleddet står først, rykker grundleddet om bag udsagnsleddet. Her står 'vi' lige efter 'spiller'."},
{"l":4486,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Hvilken forfatter har skrevet 'Charlie og chokoladefabrikken'?","o":["Astrid Lindgren","Roald Dahl","Tove Jansson","Jules Verne"],"a":"Roald Dahl","r":"Roald Dahl var en britisk forfatter med norske forældre. Han skrev også 'Matilda' og 'Heksene'."},
{"l":4502,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvad er rigtigt? 'Min lineal er 30 ___ lang.'","o":["sentimeter","centemeter","centimeter","centimetter"],"a":"centimeter","r":"Ordet begynder med c, og der er i efter t. Der er kun ét t i 'meter'."},
{"l":4520,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Vælg den rigtige form af 'at vide': 'Sidste år ___ jeg ikke, hvad en vulkan var.'","o":["vidst","ved","vide","vidste"],"a":"vidste","r":"'Sidste år' peger bagud, så der skal stå datid. 'Vidst' er tillægsform og kræver 'har' eller 'havde'."},
{"l":4542,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Vælg den rigtige form af 'at bide': 'Myggen har ___ mig i armen.'","o":["bidt","bed","bider","bide"],"a":"bidt","r":"Tillægsformen af 'at bide' er 'bidt'. 'Bed' er datid."},
{"l":4562,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Personen reparerer bilers motorer på et værksted. Hvad er stavet rigtigt?","o":["mekanikker","mekaniker","mekaniger","mekkaniker"],"a":"mekaniker","r":"Ordet har ét k hvert sted. Det slutter på -er, fordi det er et navneord om en person."},
{"l":4585,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Alle i klassen troede, at Sif var vild med fodbold. Hun havde trøjen på næsten hver dag. Så en dag spurgte Noa, hvilken spiller hun bedst kunne lide på holdet. Sif åbnede munden, lukkede den igen og kiggede ned på trøjen. – Min bror er vokset ud af den, sagde hun.' Hvad afslører det øjeblik om Sif?","o":["Hun holder med et andet hold end sin bror","Hun er vred på Noa over spørgsmålet","Hun ved ikke så meget om fodbold, som de andre tror","Hun har lige glemt spillerens navn"],"a":"Hun ved ikke så meget om fodbold, som de andre tror","r":"Hun kan ikke svare på, hvilken spiller hun bedst kan lide, og trøjen har hun bare overtaget fra sin bror. Så er hun ikke så vild med fodbold, som de andre tror."},
{"l":4600,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Klassens løbetest: Ida løb 3 km på 15 minutter i august og på 14 minutter i oktober. Anton løb på 20 minutter i august og på 16 minutter i oktober.' Hvilken slutning er rigtig?","o":["Ida forbedrede sig mest og var også hurtigst i oktober","Anton forbedrede sig mest og var hurtigst i oktober","Ida og Anton forbedrede sig lige meget fra gang til gang","Anton forbedrede sig mest, men Ida var stadig hurtigst"],"a":"Anton forbedrede sig mest, men Ida var stadig hurtigst","r":"Anton vandt fire minutter, Ida ét. Alligevel har Ida den laveste tid i oktober, så der er to ting at holde styr på."},
{"l":4619,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvad er 'at' i sætningen: 'Hun lovede, at hun ville ringe.'","o":["bindeord","navneformsmærke","biord","kendeord"],"a":"bindeord","r":"Her indleder 'at' en ledsætning med eget grundled og udsagnsled. Så er det et bindeord."},
{"l":4635,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'På havbunden i Østersøen ligger et skibsvrag. Det er ikke rustent, for det er bygget af træ. Pæleorm, som ellers spiser sig igennem træ, findes kun sjældent i det kolde og saltfattige vand i Østersøen. Derfor kan man finde vrag her, der er flere hundrede år gamle.' Hvorfor er træet bevaret?","o":["Fordi træet blev malet i gamle dage","Fordi der næsten ikke er pæleorm i vandet","Fordi rust beskytter træet mod vandet","Fordi skibet er blevet bygget af særligt træ"],"a":"Fordi der næsten ikke er pæleorm i vandet","r":"Teksten forklarer, at pæleorm ødelægger træ, men sjældent findes i det kolde og saltfattige vand."},
{"l":4657,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"I en diskussion siger man om Noah, at han 'har et es i ærmet'. Hvad betyder det?","o":["han er rigtig god til at spille kort","han har tabt noget vigtigt undervejs","han har en skjult fordel, han kan bruge","han fryser om armene og vil gerne hjem"],"a":"han har en skjult fordel, han kan bruge","r":"Billedet kommer fra kortspil: Et es gemt i ærmet er et stærkt kort, som man kan trække frem, når det passer."},
{"l":4676,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Hvad står Karius og Baktus i virkeligheden for i Thorbjørn Egners historie?","o":["Tandlæger, der borer i tænderne","Børn, der ikke vil børste tænder","Slik, der klistrer til tænderne","Bakterier, der laver huller i tænderne"],"a":"Bakterier, der laver huller i tænderne","r":"Karius og Baktus er to små trolde, men de viser det, der sker i munden: Bakterier laver huller i tænderne, når man ikke børster dem."},
{"l":4696,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Find hele udsagnsleddet i spørgsmålet: 'Har du kunnet høre musikken?'","o":["Har kunnet høre","Har du kunnet","kunnet høre","høre musikken"],"a":"Har kunnet høre","r":"Grundleddet 'du' står inde i udsagnsleddet. 'Har', 'kunnet' og 'høre' hører stadig sammen."},
{"l":4709,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket af ordene udtrykker den stærkeste følelse af ikke at kunne lide noget?","o":["irritation","afsky","utilfredshed","ærgrelse"],"a":"afsky","r":"Afsky er en meget stærk modvilje. Irritation og ærgrelse er langt mildere følelser."},
{"l":4730,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvilken stavning passer? 'Det kom helt ___ for os, at skolen lukkede tidligt.'","o":["overaskende","overraskene","overraskende","overrasgende"],"a":"overraskende","r":"Ordet har dobbelt r: ét i 'over-' og ét i '-raskende'. Det ender på -ende."},
{"l":4751,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Vælg den rigtige tid: 'Efter at hun ___ sine lektier, gik hun ud.'","o":["har lavet","laver","lave","havde lavet"],"a":"havde lavet","r":"'Gik' er datid, og lektierne blev lavet før det. Det, der ligger længst tilbage, står i førdatid."},
{"l":4772,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Læs: 'Tirsdag. I dag var jeg sur på Jonas. Det har jeg ikke sagt til nogen. Jeg skriver det kun her.' Hvilken slags tekst er det?","o":["dagbog","brev","referat","anmeldelse"],"a":"dagbog","r":"I en dagbog skriver man om sin dag og sine følelser til sig selv. Dagen øverst og 'jeg' peger på genren."},
{"l":4792,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad betyder det, at 'arbejdsløsheden' stiger?","o":["at flere får højere løn","at flere mangler et job","at flere rejser til udlandet","at flere starter egen virksomhed"],"a":"at flere mangler et job","r":"Arbejdsløse er mennesker, der gerne vil arbejde, men ikke har et job. Når tallet stiger, er der flere af dem."},
{"l":4806,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Vælg den rigtige form af 'at græde': 'Den ___ baby faldt endelig i søvn.'","o":["grædt","græd","grædende","græder"],"a":"grædende","r":"Foran et navneord beskriver den lange tillægsform, hvad nogen er i gang med. Den ender på -ende."},
{"l":4826,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvad er stavet rigtigt? 'Døren åbner ___, når du går hen til den.'","o":["autumatisk","otomatisk","automattisk","automatisk"],"a":"automatisk","r":"Ordet begynder med au og slutter på -isk. Der er kun ét t efter a."},
{"l":4845,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Solceller laver strøm, når solen skinner. Derfor giver de mest strøm om dagen og om sommeren. Men familier bruger typisk mest strøm om aftenen og om vinteren. Det er et problem, der ikke er løst med solceller alene. Batterier kan hjælpe, men de er dyre.' Hvilket problem peger teksten på?","o":["Strømmen kommer, når man bruger mindst","Solceller kan slet ikke lave strøm om vinteren","Familier bruger for lidt strøm om vinteren","Batterier kan ikke gemme strømmen"],"a":"Strømmen kommer, når man bruger mindst","r":"Teksten sammenligner, hvornår solceller producerer, og hvornår familier bruger strøm. De to tider passer ikke sammen."},
{"l":4865,"g":6,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Du skriver til kommunen om en ny cykelsti. Hvilken indledning passer bedst?","o":["Hej alle sammen, vores skolevej mangler altså en cykelsti!","Jeg skriver til jer, fordi vores skolevej mangler en cykelsti.","I er da nødt til at lave en cykelsti på vores skolevej nu.","Jeg synes bare, det er totalt dumt, at vi ikke har en cykelsti."],"a":"Jeg skriver til jer, fordi vores skolevej mangler en cykelsti.","r":"Et brev til en kommune skal være høfligt og komme til sagen. De andre indledninger lyder som en snak mellem venner eller som en skældud."},
{"l":4886,"g":6,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Sæt ind: 'Hendes ___ på nyheden var et stort smil.'","o":["reaksjon","reagtion","reaktion","reaksion"],"a":"reaktion","r":"Ordet ender på -ktion. Det staves med k, selvom udsagnsordet 'reagere' har g."},
{"l":4905,"g":6,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilket bindeord passer: 'Kasper hader regn. Alligevel gik han en tur, ___ det regnede.'","o":["eftersom","medmindre","fordi","selvom"],"a":"selvom","r":"'Alligevel' viser, at han går på trods af regnen. Det udtrykkes med 'selvom'. 'Eftersom' og 'fordi' giver en grund, og det passer ikke med 'alligevel'."},
{"l":4922,"g":6,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Mennesket har kun haft sine første skrifttegn i omkring 5.000 år. Men vi har fortalt historier i langt længere tid. Før skriften blev viden givet videre fra de gamle til de unge ved fortælling. Derfor er mange gamle myter bygget op med gentagelser og rim. Det gjorde dem lettere at huske.' Hvorfor indeholder gamle myter ifølge teksten gentagelser?","o":["Fordi det hjalp folk med at huske dem uden skrift","Fordi fortællerne havde glemt, hvad de havde sagt","Fordi det gjorde dem lettere at skrive ned","Fordi folk dengang ikke kunne lide nye historier"],"a":"Fordi det hjalp folk med at huske dem uden skrift","r":"Teksten forklarer, at viden gik mundtligt videre. Gentagelser var en hjælp til hukommelsen."},
{"l":4942,"g":6,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Når nogen 'trækker det korteste strå', hvad er der så sket?","o":["de er de allermindste i hele deres klasse","de taber i en strid eller konkurrence","de bliver færdige først af alle","de vælger den letteste løsning"],"a":"de taber i en strid eller konkurrence","r":"Man kan trække strå for at afgøre noget, og den, der får det korteste, er taberen."},
{"l":4962,"g":6,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Stine sad på bagsædet og hørte sin mor og far tale om hendes fødselsdag. De talte lavt, for de troede, hun sov. Hun havde lukkede øjne og lå helt stille, for sådan kunne man finde ud af, hvad man skulle have i gave.' Hvad gør Stine?","o":["Hun falder i søvn, fordi bilturen varer længe","Hun drømmer, at hun får en gave","Hun lader, som om hun sover, for at lytte med","Hun bliver glad, fordi hun allerede har fået gaven"],"a":"Hun lader, som om hun sover, for at lytte med","r":"Stine har lukkede øjne med vilje. Sidste del af sætningen afslører, hvorfor hun gør det."},
{"l":4982,"g":6,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Kommunens nye affaldssystem bliver dyrere, men sorteringen bliver bedre. Det sagde borgmesteren på mødet i går. Flere borgere klagede over de mange spande, som ikke kan være i små haver. Borgmesteren lovede at se på sagen, men understregede, at reglerne kommer fra staten.' Hvad gør borgmesteren til sidst?","o":["Han trækker de nye regler tilbage","Han siger, at staten skal betale for spandene","Han lover, at systemet bliver billigere til næste år","Han forklarer, at kommunen ikke selv bestemmer det hele"],"a":"Han forklarer, at kommunen ikke selv bestemmer det hele","r":"Når han henviser til staten, siger han, at kommunen ikke kan ændre alt. Det er en begrænsning af hans løfte."},
{"l":5000,"g":6,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Skolen forbyder fodbold i frikvarteret, fordi man kan komme til skade. Skal vi så også forbyde trapper?' Hvad mener skribenten?","o":["At forbuddet går for vidt","At trapperne er farlige","At fodbold er farligt","At skolen bør passe bedre på eleverne"],"a":"At forbuddet går for vidt","r":"Forslaget om trapper er retorisk. Skribenten overdriver logikken for at vise, at al risiko ikke kan forbydes."},
{"l":5017,"g":6,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"I hvilken sætning betyder 'bestemt' det samme som 'med sikkerhed'?","o":["Hun ledte efter en bestemt bog på biblioteket.","Det er bestemt ikke for sent at melde sig.","Vi har bestemt, at turen går til Odense.","Han sagde nej med en meget bestemt stemme."],"a":"Det er bestemt ikke for sent at melde sig.","r":"Som biord kan 'bestemt' forstærke en påstand. I de andre sætninger betyder det 'en særlig', 'besluttet' og 'fast'."},
{"l":5037,"g":6,"b":3,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Vælg den rigtige form af 'at skulle': 'Jeg har ___ øve mig på fløjten hele ugen.'","o":["skulle","skal","skullet","måtte"],"a":"skullet","r":"Efter 'har' står tillægsformen, og af 'at skulle' hedder den 'skullet': skal, skulle, har skullet."},
{"l":5057,"g":6,"b":3,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvilken forfatter skrev 'Jorden rundt i 80 dage'?","o":["Mark Twain","Charles Dickens","Lewis Carroll","Jules Verne"],"a":"Jules Verne","r":"Jules Verne var en fransk forfatter. Hans bøger er kendt for spændende rejser og opfindelser."},
{"l":5078,"g":6,"b":3,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad er stavet rigtigt? 'Guldfiskene svømmer rundt i et ___.'","o":["akvarium","aquarium","akvariom","akvarrium"],"a":"akvarium","r":"På dansk bruges k og v i stedet for q og u. Ordet ender på -ium."},
{"l":5100,"g":6,"b":3,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Skilt ved kiosken: Vi sælger is til børn med chokolade.' Hvorfor kan skiltet læses på to måder?","o":["'Sælger' kan betyde både forære og købe af nogen","'Med chokolade' kan høre til både 'is' og 'børn'","'Børn' kan betyde både sønner og døtre","'Is' kan betyde både vinterkulde og frossent vand"],"a":"'Med chokolade' kan høre til både 'is' og 'børn'","r":"Meningen er is med chokolade, men ordstillingen tillader også børn med chokolade. Tvetydigheden skyldes placeringen af ordene."},
{"l":5115,"g":6,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Målmanden har 'is i maven' i straffesparkskonkurrencen. Hvad betyder det?","o":["han har ondt efter at have spist noget koldt","han er uvenlig over for sine holdkammerater","han bevarer roen, selv om det er svært","han er bange og vil helst ikke spille mere"],"a":"han bevarer roen, selv om det er svært","r":"Den, der har is i maven, holder hovedet koldt under pres og lader sig ikke gå på af nerver."},
{"l":5137,"g":6,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvilket ord bruger man om en vurdering, der bygger på ens egen smag og følelser?","o":["neutral","saglig","nøjagtig","subjektiv"],"a":"subjektiv","r":"En subjektiv vurdering afhænger af den person, der laver den. Derfor kan to mennesker vurdere det samme forskelligt."},
{"l":5156,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Da orkanen i 1999 ramte Danmark, væltede millioner af træer. Skovene så ødelagte ud. Men i årene efter vrimlede det med insekter i de væltede stammer, og fuglene fulgte efter. Skovfolkene sagde, at stormen havde gjort, hvad ingen plan havde kunnet: skabt plads til nyt.' Hvad vil teksten sige om stormen?","o":["At den også gav plads til noget nyt og godt","At den kun gjorde skade i skovene og for naturen","At skovfolkene havde planlagt, at den skulle komme","At insekterne havde ødelagt træerne før stormen"],"a":"At den også gav plads til noget nyt og godt","r":"Teksten viser ødelæggelsen først og vender det derefter: Stormen gav plads til nyt liv."},
{"l":5175,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Festen skal holdes inden for budgettets 'rammer'. Hvad betyder ordet her?","o":["de træstykker omkring et billede","de grænser, der er sat","de penge, der er tilbage bagefter","de personer, der står for noget"],"a":"de grænser, der er sat","r":"Rammer betyder her det, man skal holde sig inden for. Billedrammer er kun en af ordets betydninger."},
{"l":5197,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Mange ville gerne bevare 'status quo'. Hvad betyder det?","o":["den bedst mulige løsning","en ny og bedre ordning","sådan som det er nu","et meget højt niveau"],"a":"sådan som det er nu","r":"Status quo er latin og betyder den nuværende tilstand. Den, der vil bevare den, ønsker ingen ændring."},
{"l":5216,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Holdning: Der bør være mere plads til de stille elever. Mange lærere giver karakterer for at række hånden op, men det er ikke det samme som at tænke. Fakta er, at mange elever først siger noget, når de er helt sikre. Lad os finde andre måder at vise, hvad man kan på.' Hvad er skribentens hovedpåstand?","o":["At de stille elever bør lære at tale mere højt","At alle elever skal række hånden op i alle timer","At karakterer bør afskaffes helt i folkeskolen","At lærerne bør bedømme eleverne på flere måder"],"a":"At lærerne bør bedømme eleverne på flere måder","r":"Skribenten kritiserer, at kun håndsoprækning tæller, og efterlyser 'andre måder at vise, hvad man kan på'."},
{"l":5235,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Forfatteren 'skildrer' livet på landet. Hvilket ord kan stå i stedet?","o":["beskriver","forbyder","forstyrrer","forbedrer"],"a":"beskriver","r":"At skildre er at beskrive noget, så læseren kan se det for sig."},
{"l":5256,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Pressemeddelelse: Fra 1. marts kan borgere i Vesthavn få endnu bedre service. Kommunens borgerservice flytter til en digital løsning, så du kan betjene dig selv døgnet rundt. Det fysiske kontor i Nørregade lukker samme dag. Ældre borgere kan få vejledning over telefonen.' Hvad er det, afsenderen helst undgår at fremhæve?","o":["At man kan betjene sig selv døgnet rundt","At kontoret i Nørregade bliver lukket","At det nye system er digitalt","At ændringen sker den 1. marts"],"a":"At kontoret i Nørregade bliver lukket","r":"Den dårlige nyhed står midt i teksten efter de positive ord. Teksten kalder det 'bedre service', men et kontor forsvinder."},
{"l":5276,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Hvis to elever får samme karakter, er det ikke sikkert, at de ved det samme. Den ene kan have knoklet hele året, og den anden kan have læst aftenen før. En karakter er et øjebliksbillede, ikke en historie. Alligevel bruger vi den tit, som om den fortæller alt.' Hvad kritiserer teksten?","o":["At elever læser for meget aftenen før prøven","At dygtige elever får for lave karakterer","At vi tror, at en karakter fortæller alt","At nogle elever ikke får deres karakterer at se"],"a":"At vi tror, at en karakter fortæller alt","r":"Ordene 'som om den fortæller alt' viser kritikken. En karakter siger noget, men ikke alt."},
{"l":5295,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad er en 'strategi'?","o":["en liste over ugens faste opgaver","en hurtig løsning uden nogen omtanke","en leg med mange indviklede regler","en langsigtet plan for at nå et mål"],"a":"en langsigtet plan for at nå et mål","r":"Ordet er græsk og kommer fra krigsførelse, men i dag bruges det om al slags planlægning, også i sport og erhverv."},
{"l":5302,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Læger taler ofte i 'jargon'. Hvad er det?","o":["det særlige sprog, som en gruppe bruger","den måde, man taler på i en bestemt egn","en sproglig fejl i en sætning","et ord, der er lånt fra fransk"],"a":"det særlige sprog, som en gruppe bruger","r":"Jargon er de særlige ord og vendinger i et fag eller en gruppe. Udenforstående kan have svært ved at forstå dem."},
{"l":5322,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Find ledsætningen: 'Jeg ved ikke, hvor nøglen er.'","o":["Jeg ved ikke","hvor nøglen er","nøglen er","Jeg ved"],"a":"hvor nøglen er","r":"Her er det spørgeordet 'hvor', der indleder ledsætningen. Ledsætningen fortæller, hvad jeg ikke ved."},
{"l":5342,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Læs: 'Søen ligger blank og stille. / En and glider langsomt hen. / Ingen haster, ingen larmer. / Snart går solen ned igen.' Hvilken stemning er der i digtet?","o":["munter","uhyggelig","rolig","trist"],"a":"rolig","r":"Søen er stille, anden glider langsomt, og ingen larmer. Solen går ned, men her gør det bare digtet endnu mere roligt."},
{"l":5366,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvad kalder man det 'jeg', der taler i et digt?","o":["det alvidende jeg","det faglige jeg","det skjulte jeg","det lyriske jeg"],"a":"det lyriske jeg","r":"Det 'jeg', der taler i digtet, er ikke nødvendigvis digteren selv. Derfor kaldes det det lyriske jeg."},
{"l":5385,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad betyder det, at en ny plan er 'i støbeskeen'?","o":["at den er under forberedelse","at den er ved at blive ødelagt","at den er færdig og afleveret","at den er glemt for længst"],"a":"at den er under forberedelse","r":"I en støbeske smelter man metal, før det formes. Noget i støbeskeen er altså ved at blive til."},
{"l":5400,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Lærer Bak havde altid en bog i lommen og et halstørklæde, der var for langt. Han sagde aldrig en hård sætning, men når han sænkede stemmen, blev der så stille, at man kunne høre radiatoren.' Hvad fortæller teksten om lærer Bak?","o":["Han er en lærer, som eleverne gør grin med","Han har elevernes respekt uden at råbe","Han taler så lavt, at han er svær at høre","Han taler ofte om bøgerne i sin lomme"],"a":"Han har elevernes respekt uden at råbe","r":"Det er nok, at han sænker stemmen, for at klassen tier. Det viser, at eleverne hører efter ham, selvom han aldrig er hård."},
{"l":5416,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Klasselæreren havde sat tre sætninger på tavlen. Vi taber kampen. Vi tabte kampen, men vi lærte noget. Vi har ikke vundet endnu. – Det er den samme virkelighed, sagde hun. Men hvilken sætning får jer til at træne i morgen?' Hvad vil læreren vise klassen?","o":["At det er vigtigt at bruge datid i sine sætninger","At man aldrig må sige, at man har tabt","At det betyder noget, hvordan man siger tingene","At holdet skal træne mere for at vinde"],"a":"At det betyder noget, hvordan man siger tingene","r":"Sætningerne handler om det samme, men nogle af dem giver mere lyst til at træne end andre."},
{"l":5438,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad gør man, når man 'kalder en spade for en spade'?","o":["omtaler noget ubehageligt med pæne ord","bruger finere ord, end man behøver","siger noget, man egentlig ikke mener","siger tingene lige ud, som de er"],"a":"siger tingene lige ud, som de er","r":"Talemåden betyder, at man ikke pakker noget ind, men bruger de ord, der passer."},
{"l":5461,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"I hvilken sætning betyder 'forhold' det samme som 'omstændigheder'?","o":["De arbejder under svære forhold i bjergene.","De to brødre har et godt forhold til hinanden.","Prisen er lav i forhold til kvaliteten.","Forholdet mellem drenge og piger er lige."],"a":"De arbejder under svære forhold i bjergene.","r":"Her beskriver 'forhold' de vilkår, nogen lever eller arbejder under. Ordet kan også betyde en relation eller en sammenligning."},
{"l":5482,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Forestil dig, at Jordens hele historie var én dag på 24 timer. Livet opstår tidligt om morgenen. Dinosaurerne kommer først om aftenen, og mennesket dukker først op et par sekunder før midnat. Den sammenligning giver os noget at tænke over, når vi kalder os herrer over planeten.' Hvad vil forfatteren opnå med sammenligningen?","o":["At forklare, hvornår dinosaurerne levede på Jorden","At vise, at mennesket har været her i kort tid","At vise, at mennesket er det vigtigste på planeten","At vise, at Jordens historie varer kortere, end man tror"],"a":"At vise, at mennesket har været her i kort tid","r":"De få sekunder viser, at mennesket kun har været her i kort tid, selvom vi kalder os herrer over planeten."},
{"l":5498,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvilket ord er rigtigt? 'Vindmøller laver ___ af vinden.'","o":["elektrisitet","eletricitet","elektricitet","elektricitæt"],"a":"elektricitet","r":"Inde i ordet skrives s-lyden med c, og det ender på -itet."},
{"l":5520,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken ordklasse har 'lige' i: 'Tegn en lige streg med din lineal.'","o":["biord","navneord","udsagnsord","tillægsord"],"a":"tillægsord","r":"'Lige' beskriver navneordet 'streg' og er her et tillægsord. I 'jeg kommer lige' ville det være et biord."},
{"l":5536,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Under besættelsen var der 'sabotage' mod jernbanen. Hvad betyder ordet?","o":["at ødelægge noget med vilje for at skade nogen","at reparere noget, før det går i stykker","at gemme noget, så fjenden ikke finder det","at holde en lang pause fra sit arbejde på fabrikken"],"a":"at ødelægge noget med vilje for at skade nogen","r":"Modstandsfolk ødelagde for eksempel skinner, så tyskernes tog ikke kunne køre. Derfor kendes ordet fra besættelsen."},
{"l":5558,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad skal der stå? 'Vores skole har et ___ med 20 musikere.'","o":["orkestra","orkester","orchester","orkæster"],"a":"orkester","r":"På dansk staves ordet med k og slutter på -er."},
{"l":5579,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"H.C. Andersen skrev mere end eventyr. Hvad skrev han også?","o":["Lovtekster og aviser for kongen","Lærebøger i regning og sprog","Romaner, rejsebøger og digte","Fagbøger om søfart og handel"],"a":"Romaner, rejsebøger og digte","r":"Andersen skrev blandt andet romanen 'Improvisatoren' og rejsebogen 'En Digters Bazar'. Eventyrene gjorde ham dog mest kendt."},
{"l":5597,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket ord passer: 'Far tjekkede sine lommer. Han havde ingen nøgler på ___.'","o":["ham","han","hans","sig"],"a":"sig","r":"Ordet peger tilbage på grundleddet 'han', altså far selv. Derfor hedder det 'på sig'."},
{"l":5618,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad er stavet rigtigt? 'Vi bor på tredje ___ i opgang B.'","o":["etage","ettage","etasje","etache"],"a":"etage","r":"Ordet er fransk og ender på -age, som lyder som 'asje'. Der er ét t."},
{"l":5633,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad betyder det at 'lade nåde gå for ret'?","o":["at lade andre afgøre noget for sig","at være mild i stedet for at straffe","at følge lovens ord helt nøje","at tabe en sag i retten"],"a":"at være mild i stedet for at straffe","r":"Her vælger man at tilgive, selv om man kunne have krævet en straf."},
{"l":5654,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"En firkant med fire lige lange sider og rette vinkler er et ___. Hvad er stavet rigtigt?","o":["qvadrat","kvaddrat","kvadrat","kvadrad"],"a":"kvadrat","r":"Ordet begynder med kv, har ét d og ender på t."},
{"l":5675,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvad kaldes de gamle islandske fortællinger om slægter og helte fra vikingetiden?","o":["sonetter","limericks","noveller","sagaer"],"a":"sagaer","r":"Sagaerne blev skrevet ned på Island i middelalderen. De fortæller om slægter, stridigheder og rejser i vikingetiden."},
{"l":5696,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Vælg datid af 'at tvinge': 'I går ___ stormen os til at vende om.'","o":["tvang","tvunget","tvinger","tvinge"],"a":"tvang","r":"'At tvinge' bøjes tvinger, tvang, har tvunget. 'I går' kræver datid."},
{"l":5716,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Alle taler om, at mobiler stjæler elevernes opmærksomhed. Men da vores klasse havde mobilfri uge, var der lige så meget uro i timerne som før. Måske skal vi lede efter forklaringen et andet sted.' Hvad mener skribenten sandsynligvis?","o":["Eleverne skal have lov at bruge mobilen i timerne","Det er nok ikke mobilerne, der giver uroen","Der kom mere uro i den mobilfri uge","Uroen kommer af, at lærerne er for strenge"],"a":"Det er nok ikke mobilerne, der giver uroen","r":"Uroen forsvandt ikke, da mobilerne var væk, og derfor peger skribenten på en anden forklaring. Der stod 'lige så meget uro', ikke mere."},
{"l":5738,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Find det direkte objekt (genstandsleddet): 'Emil fandt en gammel mønt på stranden.'","o":["Emil","fandt","en gammel mønt","på stranden"],"a":"en gammel mønt","r":"Spørg: Hvad fandt Emil? Svaret er genstandsleddet. 'På stranden' svarer på hvor."},
{"l":5759,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad skal der stå? 'Flagstangen står helt ___, så den peger lige op.'","o":["lodrett","loddret","lorret","lodret"],"a":"lodret","r":"Ordet består af 'lod' og 'ret'. Der er ét d og ét t, selvom d'et næsten ikke høres."},
{"l":5776,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Sæt det rigtige ord ind: 'Vi har brug for en grundig ___ af problemet.'","o":["undersøgelse","undersøge","undersøgende","undersøgt"],"a":"undersøgelse","r":"Efter 'en grundig' skal der stå et navneord. Endelsen -else laver udsagnsordet 'undersøge' om til et navneord."},
{"l":5798,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Sæt det rigtige talord ind: 'Min far fylder ___ år i maj, og det skal fejres.'","o":["halvtres","halvtreds","halvtredds","haltreds"],"a":"halvtreds","r":"Ordet betyder 50 og ender på -treds med stumt d. Husk også v'et i 'halv'."},
{"l":5815,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvad er ledsætningen i: 'Da solen skinnede, spiste vi ude i haven.'?","o":["spiste vi ude i haven","solen skinnede","Da solen skinnede","ude i haven"],"a":"Da solen skinnede","r":"En ledsætning kan ikke stå alene, og den begynder her med bindeordet 'da'. Bindeordet hører med til ledsætningen, for uden det ville 'solen skinnede' være en hovedsætning."},
{"l":5836,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad handler 'globalisering' om?","o":["at jordens temperatur stiger år for år","at lande lukker deres grænser helt","at folk flytter væk fra byerne og ud på landet","at lande og mennesker bliver tættere forbundet"],"a":"at lande og mennesker bliver tættere forbundet","r":"Ordet kommer af 'globus'. Handel, rejser og internet gør, at det, der sker ét sted på kloden, påvirker andre steder."},
{"l":5852,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvilken appelform bruger en debattør, når hun overbeviser med tal, fakta og fornuftige argumenter?","o":["logos","etos","patos","ironi"],"a":"logos","r":"Logos appellerer til fornuften med fakta og logik. Patos går på følelserne, og etos handler om afsenderens troværdighed."},
{"l":5873,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"En idrætsforening har 'vedtægter'. Hvad er det?","o":["foreningens liste over medlemmer","foreningens skrevne regler","foreningens årlige regnskab","foreningens træningstider"],"a":"foreningens skrevne regler","r":"Vedtægter fastlægger, hvordan en forening skal drives, for eksempel hvordan bestyrelsen bliver valgt."},
{"l":5896,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Der er 'moms' på de fleste varer i Danmark. Hvad er det?","o":["en rabat til kunder, der køber meget","et gebyr, der går til butikkens ejer","en afgift til staten, der ligger i prisen","en løn til de ansatte i butikken"],"a":"en afgift til staten, der ligger i prisen","r":"Moms hedder officielt merværdiafgift. Butikken opkræver den hos kunden og betaler den videre til staten."},
{"l":5914,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvad er relativsætningen i: 'Bogen, som Ida lånte, handler om vikinger.'?","o":["Bogen handler om vikinger","om vikinger","Ida lånte","som Ida lånte"],"a":"som Ida lånte","r":"En relativsætning siger noget nærmere om et navneord. Her fortæller 'som Ida lånte', hvilken bog der er tale om."},
{"l":5933,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Løver er 'karnivorer'. Hvad betyder det?","o":["de spiser kød","de spiser planter","de er aktive om natten","de lever på savannen"],"a":"de spiser kød","r":"Ordet kommer af det latinske 'caro', som betyder kød. Dyr, der spiser planter, kaldes herbivorer."},
{"l":5954,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvilket træk er typisk for et sagn?","o":["Det slutter altid med en moral, som dyrene har lært","Det er knyttet til et bestemt sted og fortælles som sandt","Det er en personlig tekst, som tænker højt om et emne","Det er skrevet af en journalist på et bestemt tidspunkt"],"a":"Det er knyttet til et bestemt sted og fortælles som sandt","r":"Et sagn hænger sammen med et bestemt sted eller en bestemt person og fortælles, som om det virkelig er sket. Det adskiller det fra eventyret."},
{"l":5971,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Læs: 'Holger Danske sover dybt under Kronborg. Når Danmark er i nød, vågner han.' Hvilken genre stammer fortællingen fra?","o":["fabel","myte","sagn","eventyr"],"a":"sagn","r":"Fortællingen er knyttet til et rigtigt sted, Kronborg, og er blevet givet videre fra person til person. Det er typisk for sagnet."},
{"l":5993,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"'Urbanisering' bruges i både geografi og samfundsfag. Hvad beskriver ordet?","o":["at flere og flere flytter fra by til land","at byerne bliver renere og grønnere","at landbruget får større maskiner","at flere og flere flytter fra land til by"],"a":"at flere og flere flytter fra land til by","r":"Ordet kommer af det latinske 'urbs', som betyder by. Når en større del af befolkningen bor i byer, taler man om urbanisering."},
{"l":6005,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvad undersøger du, når du beskriver miljøet i en novelle?","o":["Hvor og hvornår handlingen foregår","Hvordan personerne ser ud","Hvem der fortæller historien","Hvad teksten gerne vil sige til læseren"],"a":"Hvor og hvornår handlingen foregår","r":"Miljøet er de omgivelser, personerne lever i: sted, tid og de sociale forhold."},
{"l":6023,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad gør 'klorofyl' i en plante?","o":["fører vand fra roden op til bladene","opfanger sollys og gør planten grøn","beskytter planten mod insekter med gift","lagrer frø, så planten kan spire igen"],"a":"opfanger sollys og gør planten grøn","r":"Klorofyl er det grønne farvestof i bladene. Det opfanger den lysenergi, planten bruger til fotosyntese."},
{"l":6046,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"I en rapport står der: 'Endvidere viser tallene en stigning.' Hvilket ord kan stå i stedet for 'endvidere'?","o":["derimod","alligevel","desuden","måske"],"a":"desuden","r":"'Endvidere' tilføjer en ny oplysning til det, der allerede er sagt. 'Derimod' ville i stedet vise en modsætning."},
{"l":6068,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Skolen har fået et gratis hæfte om sund morgenmad. Hæftet anbefaler havregryn, frugt og to glas mælk hver morgen, og tallene om kalk og protein er rigtige nok. Der står intet om, at man også kan få kalk fra andre fødevarer. På bagsiden står der med småt, at hæftet er betalt af en stor mælkevirksomhed.' Hvorfor kan hæftet give et skævt billede, selv om tallene er rigtige?","o":["Mælkevirksomheden bruger tal, som ingen andre kan tjekke efter","Hæftet er gratis, og gratis hæfter er sjældent lavet ordentligt","Hæftet handler om morgenmad, og den spiser eleverne jo derhjemme","Mælkevirksomheden betaler, så den fortæller kun det, der sælger mælk"],"a":"Mælkevirksomheden betaler, så den fortæller kun det, der sælger mælk","r":"Rigtige tal kan stadig give et skævt billede, hvis de er udvalgt. Når en mælkevirksomhed betaler, må man spørge, hvad der er ladet ude, her at kalk også findes i anden mad."},
{"l":6084,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad skal der stå? 'Hvis du ___ dyret præcist, kan de andre gætte, hvad det er.'","o":["beskriver","beskrive","beskrivver","beskriverer"],"a":"beskriver","r":"Ordet står i nutid efter grundleddet 'du' og får derfor -r, også i en ledsætning."},
{"l":6100,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Sælgeren sagde, at tilbuddet kun gælder i dag. Det sagde han også i går.' Hvad antyder teksten?","o":["At sælgeren har glemt, hvad dag det er","At sælgeren vil få folk til at skynde sig","At tilbuddet virkelig er det bedste i byen","At varen er blevet billigere i dag"],"a":"At sælgeren vil få folk til at skynde sig","r":"Han sagde det samme i går, så 'kun i dag' passer ikke. Det er et kendt salgstrick, der skal få folk til at købe hurtigt."},
{"l":6121,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad er et 'plagiat'?","o":["en bog, der er skrevet af mange forfattere","en tekst, der er oversat fra et andet sprog","en tekst, man har kopieret og kaldt sin egen","en aftale om at få udgivet en bog"],"a":"en tekst, man har kopieret og kaldt sin egen","r":"Plagiat er at kopiere andres tekst eller idé uden at sige, hvor den kommer fra. Det gælder også skoleopgaver."},
{"l":6140,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilken sætning om dyrene i zoo skriver 'blandt andet' rigtigt?","o":["Vi så b.l.a. løver og zebraer.","Vi så bl.an. løver og zebraer.","Vi så b.a. løver og zebraer.","Vi så bl.a. løver og zebraer."],"a":"Vi så bl.a. løver og zebraer.","r":"'Blandt' forkortes bl. og 'andet' forkortes a., så det samlede udtryk bliver bl.a."},
{"l":6159,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken verbalform passer: 'Uret er ___ for ti minutter siden.'?","o":["stoppet","stoppede","stoppe","stopper"],"a":"stoppet","r":"Efter 'er' i førnutid står kort tillægsform: 'er stoppet'. 'Stoppede' er datid og lyder næsten ens, men det kan ikke stå sammen med 'er' her."},
{"l":6181,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Et firma går 'konkurs'. Hvad sker der?","o":["det bliver købt af et større firma i udlandet","det kan ikke betale sin gæld og må lukke","det flytter sin produktion til et andet land","det deltager i en konkurrence om en pris"],"a":"det kan ikke betale sin gæld og må lukke","r":"Ved en konkurs er der ikke penge nok til at betale regningerne. Firmaets værdier bliver solgt, og pengene fordelt til dem, det skylder."},
{"l":6200,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Naboen var en venlig mand, som hver eneste dag kom over for at fortælle os, hvor vi havde parkeret forkert, klippet hækken skævt eller stillet skraldespanden uheldigt.' Hvordan skal ordet 'venlig' læses?","o":["Bogstaveligt, for manden hjælper familien","Neutralt, for ordet har ingen betydning her","Ironisk, for manden er snarere en plage","Vredt, for fortælleren truer med at flytte"],"a":"Ironisk, for manden er snarere en plage","r":"Eksemplerne viser en, der blander sig hele tiden. Det gør 'venlig' til et ironisk ord."},
{"l":6214,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad skal der stå? 'Hun sprang over to meter, og det var ___.'","o":["imponerene","imponnerende","inponerende","imponerende"],"a":"imponerende","r":"Ordet er dannet af 'imponere' med -ende, så d'et skal med. Foran p skrives der m, ikke n."},
{"l":6233,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Navneordet 'forurening' er dannet af et udsagnsord. Hvilket?","o":["forurene","uren","forurenende","forurenet"],"a":"forurene","r":"Endelsen -ing sættes på stammen af et udsagnsord. Navneformen er 'forurene', mens de andre svar er tillægsord eller tillægsformer."},
{"l":6255,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Kurverne viser luft og vand ved Lillebæk Strand. Luften er varmest i juli med 22 grader. Vandet er varmest i august med 19 grader. I september er luften 16 grader og vandet 17 grader.' Hvad viser kurverne om vandet i forhold til luften?","o":["Vandet er altid koldere end luften på stranden","Vandet bliver varmest senere end luften","Vandet er varmere end luften hele sommeren","Luft og vand er varmest i præcis den samme måned"],"a":"Vandet bliver varmest senere end luften","r":"Luften er varmest i juli, vandet i august. I september er vandet ganske vist varmere end luften, så 'altid koldere' passer ikke."},
{"l":6278,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"'Journalisten dækker valget i USA.' Hvad betyder 'dækker' her?","o":["skjuler","betaler for","laver nyheder om","stiller op til"],"a":"laver nyheder om","r":"I mediesprog betyder 'dække' at følge en begivenhed og fortælle om den. Ordets almindelige betydning er at lægge noget ovenpå."},
{"l":6300,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Efter hvilket ord skal der altid komma: 'Da Emil opdagede at hans taske var væk blev han bange.'?","o":["taske","blev","bange","væk"],"a":"væk","r":"Ledsætningen 'Da Emil opdagede at hans taske var væk' står først og slutter efter 'væk'."},
{"l":6308,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Nilen ender i et 'delta'. Hvad er det?","o":["et vifteformet område, hvor floden løber ud","et vandfald, hvor floden falder ned","en dæmning, der standser flodens vand","en dyb kløft, floden har skåret i klippen"],"a":"et vifteformet område, hvor floden løber ud","r":"Deltaet dannes af det materiale, floden fører med sig. Navnet kommer af det græske bogstav delta, som ligner en trekant."},
{"l":6328,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvad er forskellen på et folkeeventyr og et kunsteventyr?","o":["Folkeeventyret har en kendt forfatter, kunsteventyret er mundtligt","Folkeeventyret er mundtligt overleveret, kunsteventyret har en forfatter","Folkeeventyret handler om dyr, kunsteventyret handler kun om mennesker","Folkeeventyret er nyt, og kunsteventyret er meget ældre end middelalderen"],"a":"Folkeeventyret er mundtligt overleveret, kunsteventyret har en forfatter","r":"Folkeeventyr er gået fra mund til mund og har ingen kendt forfatter. Et kunsteventyr er skrevet af en bestemt forfatter, f.eks. H.C. Andersen."},
{"l":6346,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad betyder det at være 'forudindtaget'?","o":["at have tilmeldt sig i meget god tid","at være den første, der får noget at vide","at have bestemt sig uden at kende sagen","at være optaget af at planlægge fremtiden"],"a":"at have bestemt sig uden at kende sagen","r":"Den, der er forudindtaget, har allerede en mening og er ikke åben for nye argumenter. Ordet minder om 'fordom'."},
{"l":6368,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Det er en 'norm' at sige tak for mad. Hvad er en norm?","o":["en lov, man kan få bøde for at bryde","en vane, kun én enkelt familie har","en opskrift på, hvordan man laver maden","en uskreven regel for god opførsel"],"a":"en uskreven regel for god opførsel","r":"Normer står ikke i loven, men de fleste følger dem. Bryder man dem, får man måske sure miner, ikke en straf fra retten."},
{"l":6391,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvilket dansk ord betyder det samme som 'referendum'?","o":["folkeafstemning","mistillidsvotum","lovforslag","kommunalvalg"],"a":"folkeafstemning","r":"Ved et referendum stemmer vælgerne direkte om en bestemt sag. Det adskiller sig fra et valg, hvor man vælger personer eller partier."},
{"l":6409,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Jeg elsker mine forældre. Men når de spørger: Hvordan gik det i skolen?, og jeg svarer: Fint, så ved vi alle tre, at samtalen er forbi.' Hvad mener skribenten om spørgsmålet?","o":["Det er et spørgsmål, som forældre ikke har lov til at stille","Det er en vane, der sjældent fører til en rigtig snak","Det viser, at forældrene er ligeglade med deres barn","Det er svært at svare på, fordi skoledagen var dårlig"],"a":"Det er en vane, der sjældent fører til en rigtig snak","r":"Spørgsmålet kommer hver gang, og samtalen stopper ved 'Fint'. Skribenten skriver 'Jeg elsker mine forældre', så det er ikke ment som kritik af dem."},
{"l":6430,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Læs: 'Hvor er det dog skønt, sagde Jonas og så ud på den fjerde dag med silende regn i sommerferien.' Hvilket virkemiddel bruger Jonas?","o":["personifikation","sammenligning","ironi","allitteration"],"a":"ironi","r":"Jonas siger det modsatte af det, han mener. Situationen viser, at han slet ikke synes, at det er skønt."},
{"l":6448,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvilket navneord er stavet rigtigt? Det er noget, man har krav på, for eksempel at gå i skole.","o":["retighed","rettihed","rettiged","rettighed"],"a":"rettighed","r":"Ordet har dobbelt-t, og det stumme g foran -hed skal med."},
{"l":6473,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad er advarslen i udtrykket 'læg ikke alle æg i én kurv'?","o":["at man ikke skal satse alt på én mulighed","at man skal passe på det, man har købt","at man ikke skal tage mere, end man kan bære","at man skal dele sine ting med andre"],"a":"at man ikke skal satse alt på én mulighed","r":"Hvis kurven tabes, er alle æggene væk. Derfor er det klogere at sprede sin risiko."},
{"l":6496,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvem er det, der 'trækker i trådene' i en sag?","o":["den, der først opdager sagen","den, der skjult styrer det hele","den, der skriver om sagen i avisen","den, der bliver ramt hårdest af sagen"],"a":"den, der skjult styrer det hele","r":"Billedet kommer fra dukketeatret, hvor dukkeføreren står skjult og styrer dukkerne med tråde."},
{"l":6500,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Vi har haft tre skoleledere på to år. Den nyeste skriver i sit velkomstbrev, at hun vil skabe ro og kontinuitet.' Hvad kan man slutte om skolen?","o":["Den nye leder bliver nok heller ikke længe","Der er for få elever på skolen i år","Der har ikke været ro i ledelsen","Skolens to første ledere var meget gode"],"a":"Der har ikke været ro i ledelsen","r":"Tre ledere på to år er mange. Når den nye vil skabe ro, tyder det på, at der ikke har været ro."},
{"l":6521,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket ord skal stå i skriftsprog: 'Har du ___ idé om, hvor mine nøgler er?'?","o":["nogle","noget","hvilke","nogen"],"a":"nogen","r":"'Idé' står i ental og er fælleskøn, så der skal stå 'nogen'. 'Nogle' er flertal, og 'noget' passer til intetkønsord."},
{"l":6541,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Sportsklubben skriver til naboerne: Vi beklager, hvis nogen skulle have følt sig generet af støjen fra vores fest.' Hvordan virker denne undskyldning?","o":["Den lyder ikke, som om klubben rigtig mener det","Den lyder, som om klubben virkelig er ked af det","Den lyder, som om klubben lover at dæmpe sig","Den lyder, som om det hele er naboernes skyld"],"a":"Den lyder ikke, som om klubben rigtig mener det","r":"Klubben siger ikke 'vi larmede, undskyld'. Den siger kun 'hvis nogen skulle have følt sig generet'. Så indrømmer den ikke rigtig, at den har gjort noget forkert."},
{"l":6563,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'En kurve fra Nordskolen viser, at elever, der sover meget, også svarer, at de trives. Kurven viser altså, skriver skolebladet, at god søvn giver god trivsel.' Hvad overser skolebladet?","o":["At kurven er tegnet på grundlag af elevernes svar","At det lige så godt kan være omvendt","At søvn normalt bliver målt i timer pr. nat","At nogle elever sover mere end andre"],"a":"At det lige så godt kan være omvendt","r":"Det kan også være, at elever, der trives, sover bedre. En sammenhæng fortæller ikke, hvad der er årsag, og hvad der er virkning."}
]$$::jsonb) AS e
JOIN (VALUES
  ('s', 'stavning', 'recall', 'factual', 'surface_association'),
  ('o', 'ordforråd', 'recall', 'factual', 'surface_association'),
  ('g', 'grammatik', 'application', 'applied', 'overgeneralization'),
  ('t', 'tegnsætning', 'application', 'applied', 'overgeneralization'),
  ('l', 'læseforståelse', 'comprehension', 'conceptual', 'surface_association'),
  ('f', 'litteratur', 'analysis', 'inferential', 'surface_association')
) AS m(k, concept, skill, dtype, mis) ON m.k = e->>'k';
